package oruby

// #include "go-mrb.h"
// #include "go-aot.h"
// #include "oruby-vm-compat.h"
// static inline void aot_chill_string(mrb_value value) {
//   if (mrb_string_p(value)) mrb_basic_ptr(value)->flags |= ORUBY_STRING_CHILLED;
// }
import "C"
import (
	"encoding/base64"
	"errors"
	"fmt"
	"math"
	"os"
	"unsafe"
)

// Runtime support for Go code generated by the ORuby AOT compiler (compiler/).
//
// Compiled methods and blocks are Go functions of type AotFunc. They are
// registered as C functions, so all mruby API calls that may raise are made
// through protected C shims (go-aot.h). A raised exception stays pending in
// mrb->exc and is propagated by compiled code as a Go error until it reaches
// a rescue/ensure handler or the C trampoline, which re-raises it in mruby.

// AotFunc is the signature of a compiled irep (method, block or class body).
type AotFunc func(mrb *MrbState, self Value, args []Value, blk Value, cx *AotCtx, up *AotEnv) (Value, error)

// AotCref is the lexical class nesting used for constant lookup.
type AotCref struct {
	Class Value
	Up    *AotCref
}

// AotCtx is the method level context shared by a method and its blocks.
type AotCtx struct {
	Cref      *AotCref
	DefTarget Value          // target class override (instance_exec/class_exec blocks)
	Mid       MrbSym         // method name, for super
	Super     unsafe.Pointer // *C.struct_RClass the method was found in, for super
}

// AotEnv is a register file of a compiled frame captured by blocks.
// R aliases the elements of Ary, an mruby Array visible to the GC. The last
// element of Ary links to the parent frame Array, so blocks keep their whole
// lexical chain alive.
type AotEnv struct {
	R      []Value
	Ary    Value
	Up     *AotEnv
	Root   unsafe.Pointer // *C.struct_mrb_context of the thread this frame belongs to
	Active uint64         // block literal call sites (by child index) currently running
	Done   bool           // frame has returned
}

// AotError is a Ruby exception propagated through compiled Go frames.
type AotError struct {
	mrb *MrbState
	Exc Value
}

func (e *AotError) Error() string {
	if e.mrb == nil || e.Exc.IsNil() {
		return "ruby exception"
	}
	if e.Exc.Type() == MrbTTBreak {
		return "LocalJumpError: break from proc-closure"
	}
	mrb := e.mrb
	saved := mrb.p.exc
	mrb.p.exc = nil
	cls := mrb.ClassOf(e.Exc).Name()
	msg := mrb.aotInspectMessage(e.Exc)
	mrb.p.exc = saved
	return fmt.Sprintf("%v: %v", cls, msg)
}

func (mrb *MrbState) aotInspectMessage(exc Value) string {
	sym := Sym_message
	v := Value{C._aot_funcall(mrb.p, exc.v, C.mrb_sym(sym), 0, nil, C.mrb_nil_value())}
	if mrb.p.exc != nil {
		mrb.p.exc = nil
		return "(error in message)"
	}
	if v.Type() == MrbTTString {
		return v.String()
	}
	return ""
}

// AotIntOpsRedefined reports whether the program redefined an Integer
// operator that compiled code evaluates inline (+ - * / == < <= > >= and
// % & | ^ << >>, the extra slots of the bop_redefined patch). It
// reads mruby's redefinition bits directly, without a cgo call, so generated
// code can check it on every operation.
func (mrb *MrbState) AotIntOpsRedefined() bool {
	return mrb.p.bop_redefined&(C._AOT_INT_BOP_MASK|C._AOT_INT_OPS2_MASK) != 0
}

// AotIntBitOpsRedefined reports whether Integer#% & | ^ << >> was redefined
// (or a module prepended): one mask test on the extra slots of mruby's
// bop_redefined. A user class defining one of these names does not set it.
func (mrb *MrbState) AotIntBitOpsRedefined() bool {
	return mrb.p.bop_redefined&C._AOT_INT_OPS2_MASK != 0
}

// AotAryPushRedefined reports whether Array#<< was redefined.
func (mrb *MrbState) AotAryPushRedefined() bool {
	return mrb.p.bop_redefined&C._AOT_ARY_PUSH_BIT != 0
}

// AotFloatOpsRedefined is AotIntOpsRedefined for the Float operators.
func (mrb *MrbState) AotFloatOpsRedefined() bool {
	return mrb.p.bop_redefined&C._AOT_FLOAT_BOP_MASK != 0
}

// AotErr returns current pending exception as Go error
func (mrb *MrbState) AotErr() error {
	if mrb.p.exc == nil {
		return &AotError{mrb, nilValue}
	}
	return &AotError{mrb, Value{C.mrb_obj_value(unsafe.Pointer(mrb.p.exc))}}
}

// AotBoundaryErr snapshots a pending exception at the public compiled-program
// boundary. Internal generated frames continue to use AotErr for dispatch.
func (mrb *MrbState) AotBoundaryErr() error {
	if mrb.p.exc == nil {
		return errors.New("compiled Ruby call failed without a pending exception")
	}
	value := Value{C.mrb_obj_value(unsafe.Pointer(mrb.p.exc))}
	if value.Type() == MrbTTBreak {
		return &rubyControlFlow{state: mrb, value: value}
	}
	return mrb.exceptionError(value)
}

// HasExc returns true if exception is pending
func (mrb *MrbState) HasExc() bool { return mrb.p.exc != nil }

// AotIntrinsicID identifies a registered Go-extension method eligible for
// guarded direct Go-to-Go dispatch from AOT-compiled code.
type AotIntrinsicID int

const (
	AotIntrinsicFastBlank AotIntrinsicID = iota
	AotIntrinsicFastBlankAs
	AotIntrinsicEscapeHTML
	AotIntrinsicEscapeURL
	AotIntrinsicXXH32
	AotIntrinsicXXH64
	AotIntrinsicZstdCompress
	AotIntrinsicZstdDecompress
	AotIntrinsicBrotliDeflate
	AotIntrinsicBrotliInflate
	aotIntrinsicCount
)

type aotIntrinsicSlot struct {
	cls    *C.struct_RClass // expected receiver class (exact class or module singleton class)
	modPtr uintptr          // non-zero for module/class methods: expected receiver pointer
	mid    C.mrb_sym        // method symbol
	method C.mrb_method_t   // expected original method entry in mruby's method cache
	flag   bool             // optional per-intrinsic runtime flag (e.g. EscapeUtils.html_secure)
	way0   uint32           // index of the first of the two method cache entries of (cls, mid), fixed for the slot
}

var (
	aotFixnumTemplate = Value{C.mrb_fixnum_value(0)}
	aotFloatTemplate  = Value{C.mrb_float_value(nil, 0)}
)

type aotState struct {
	breakClass        RClass
	returnClass       RClass
	symVal            MrbSym
	symTag            MrbSym
	symIdx            MrbSym
	symDispatch       MrbSym
	symSend           MrbSym // send, __send__, public_send: see aotSendFamily
	symSend2          MrbSym
	symPubSend        MrbSym
	sigVals           map[aotSigKey]Value
	symCall           MrbSym
	topCx             *AotCtx
	blocks            map[int64]*aotBlockData
	nextBlock         int64
	trampIdx          int
	methods           []*aotMethod
	depth             int
	intDisabled       int
	envCallbackPtr    unsafe.Pointer
	attrReaderPtr     unsafe.Pointer
	attrWriterPtr     unsafe.Pointer
	structRefPtr      unsafe.Pointer
	dataRefPtr        unsafe.Pointer
	dataDirectRefPtrs [4]unsafe.Pointer
	argBuf            [aotMaxDirectDepth + 2][2]Value
	intrinsics        [aotIntrinsicCount]aotIntrinsicSlot
	coreIntrinsics    [aotCoreCount]aotIntrinsicSlot
	compiledMethods   []C.mrb_method_t
}

type aotMethod struct {
	fn      AotFunc
	cx      *AotCtx
	needCtx bool
}

// aotMaxDirectDepth limits nesting of direct Go calls; deeper calls go
// through the VM, which reports SystemStackError.
const aotMaxDirectDepth = 200

// AotPending is a marker stored by OP_EXCEPT when a return or jump is
// pending through an ensure clause (never a regular Ruby value).
var AotPending = Value{C.mrb_undef_value()}

// AotInit prepares state for compiled code. It is safe to call many times.
func (mrb *MrbState) AotInit() {
	if mrb.aot != nil && mrb.aot.topCx != nil {
		return
	}
	C._aot_init(mrb.p)
	mrb.EnableGoFibers() // a Fiber.yield must cross the Go frames of compiled code
	st := mrb.aot
	if st == nil {
		st = &aotState{}
	}
	exc := mrb.EExceptionClass()
	st.breakClass = mrb.DefineClass("ORubyAotBreak", exc)
	st.returnClass = mrb.DefineClass("ORubyAotReturn", exc)
	st.symVal = IvSym___v
	st.symTag = IvSym___t
	st.symIdx = IvSym___i
	st.symDispatch = Sym___aot_dispatch__
	st.symSend = mrb.Intern("send")
	st.symSend2 = mrb.Intern("__send__")
	st.symPubSend = mrb.Intern("public_send")
	st.symCall = Sym_call
	st.topCx = &AotCtx{}
	st.blocks = make(map[int64]*aotBlockData)
	st.envCallbackPtr = C._aot_env_callback_ptr()
	st.attrReaderPtr = C._aot_attr_reader_ptr()
	st.attrWriterPtr = C._aot_attr_writer_ptr()
	C._aot_struct_data_ref_ptrs(mrb.p, &st.structRefPtr, &st.dataRefPtr, &st.dataDirectRefPtrs[0])
	mrb.aot = st
	st.trampIdx = mrb.registerMrbFuncT(mrb.aotBlockTrampoline)
	mrb.aotInitCoreIntrinsics(st)
	C.orb_bop_x_arm(mrb.p) // % & | ^ << >> ** <=> and Array#<<: the methods in force now are the builtins
}

// AotRegisterInstanceIntrinsic records a Go-extension instance method on cls
// (e.g. String#blank?) for guarded zero-cgo AOT dispatch.
func (mrb *MrbState) AotRegisterInstanceIntrinsic(id AotIntrinsicID, cls RClass, mid MrbSym) {
	if id < 0 || id >= aotIntrinsicCount {
		return
	}
	if mrb.aot == nil {
		mrb.aot = &aotState{}
	}
	var found C.mrb_bool
	m := C._aot_intrinsic_method(mrb.p, cls.p, C.mrb_sym(mid), &found)
	if !bool(found) {
		return
	}
	s := &mrb.aot.intrinsics[id]
	s.cls = cls.p
	s.modPtr = 0
	s.mid = C.mrb_sym(mid)
	s.method = m
}

// AotRegisterModuleIntrinsic records a Go-extension module/class method on mod
// (e.g. Zstd.compress, XXhash.xxh64) for guarded zero-cgo AOT dispatch.
func (mrb *MrbState) AotRegisterModuleIntrinsic(id AotIntrinsicID, mod RClass, mid MrbSym) {
	if id < 0 || id >= aotIntrinsicCount {
		return
	}
	if mrb.aot == nil {
		mrb.aot = &aotState{}
	}
	scls := C._aot_singleton_class_ptr(mrb.p, mod.Value().v)
	var found C.mrb_bool
	m := C._aot_intrinsic_method(mrb.p, scls, C.mrb_sym(mid), &found)
	if !bool(found) {
		return
	}
	s := &mrb.aot.intrinsics[id]
	s.cls = scls
	s.modPtr = mod.Value().Pointer()
	s.mid = C.mrb_sym(mid)
	s.method = m
}

// AotSetIntrinsicFlag updates the auxiliary runtime boolean on an intrinsic
// slot (e.g. EscapeUtils.html_secure).
func (mrb *MrbState) AotSetIntrinsicFlag(id AotIntrinsicID, v bool) {
	if id < 0 || id >= aotIntrinsicCount {
		return
	}
	if mrb.aot == nil {
		mrb.aot = &aotState{}
	}
	mrb.aot.intrinsics[id].flag = v
}

// AotIntrinsicFlag reads the auxiliary runtime boolean on an intrinsic slot
// without cgo.
func (mrb *MrbState) AotIntrinsicFlag(id AotIntrinsicID) bool {
	if mrb.aot == nil || id < 0 || id >= aotIntrinsicCount {
		return false
	}
	return mrb.aot.intrinsics[id].flag
}

// aotObjPtr extracts the C heap object pointer from an mrb_value without cgo
// or uintptr->unsafe.Pointer conversion.
func aotObjPtr(v Value) unsafe.Pointer {
	return *(*unsafe.Pointer)(unsafe.Pointer(&v.v))
}

// aotMethodCacheWay0 mirrors the C lookup in ORubyVMCompat.method_cache_groups.
func aotMethodCacheWay0(cls *C.struct_RClass, mid C.mrb_sym) uint32 {
	group := (uint32(mid) & (C.ORUBY_MC_GROUPS - 1)) * C.ORUBY_MC_GROUP_SIZE
	key := (uintptr(unsafe.Pointer(cls)) >> 4) ^ uintptr(mid)
	hash := uint32(key ^ (key << 2) ^ (key >> 2))
	return group + 2*(hash&(C.ORUBY_MC_GROUP_SIZE/2-1))
}

// AotIntrinsicOK checks in pure Go (zero cgo calls) that calling the registered
// intrinsic slot on recv will resolve to the exact original extension method
// with no monkey-patching, singleton override, subclass, prepend, or refinement.
func (mrb *MrbState) AotIntrinsicOK(id AotIntrinsicID, recv Value) bool {
	if mrb.aot == nil || id < 0 || id >= aotIntrinsicCount {
		return false
	}
	s := &mrb.aot.intrinsics[id]
	if s.cls == nil {
		return false
	}
	ptr := recv.Pointer()
	if ptr <= 65536 {
		return false
	}
	up := aotObjPtr(recv)
	if s.modPtr != 0 {
		if ptr != s.modPtr {
			return false
		}
		if (*C.struct_RBasic)(up).c != s.cls {
			return false
		}
	} else {
		if recv.Type() != MrbTTString {
			return false
		}
		if (*C.struct_RBasic)(up).c != s.cls {
			return false
		}
	}
	// Any active refinement disables direct bypass so refined methods dispatch normally.
	if (mrb.p.refined_mids[0] | mrb.p.refined_mids[1] | mrb.p.refined_mids[2] | mrb.p.refined_mids[3]) != 0 {
		return false
	}
	// Verify mruby's 2-way method cache still maps (s.cls, s.mid) to s.method.
	way0 := aotMethodCacheWay0(s.cls, s.mid)
	mc0 := &mrb.p.cache[way0]
	if mc0.c == s.cls && mc0.mid == s.mid {
		return mc0.m == s.method
	}
	mc1 := &mrb.p.cache[way0+1]
	if mc1.c == s.cls && mc1.mid == s.mid {
		return mc1.m == s.method
	}
	return false
}

// AotStringBytes returns a zero-copy, read-only byte slice of a Ruby String
// without any cgo call. The slice must not be mutated or retained past the
// current call (mruby GC could collect or reallocate the underlying string).
func (mrb *MrbState) AotStringBytes(v Value) ([]byte, bool) {
	if v.Type() != MrbTTString {
		return nil, false
	}
	if v.Pointer() <= 65536 {
		return nil, false
	}
	up := aotObjPtr(v)
	flags := (*(*uint32)(unsafe.Add(up, 8))) >> 12
	if (flags & 8) != 0 { // MRB_STR_EMBED
		n := int((flags >> 4) & 31)
		if n == 0 {
			return nil, true
		}
		return unsafe.Slice((*byte)(unsafe.Add(up, 12)), n), true
	}
	n := int(*(*int64)(unsafe.Add(up, 16)))
	if n <= 0 {
		return nil, true
	}
	p := *(**byte)(unsafe.Add(up, 32))
	if p == nil {
		return nil, true
	}
	return unsafe.Slice(p, n), true
}

// AotFixnum builds a Fixnum Value in pure Go without cgo.
func AotFixnum(n int64) Value {
	v := aotFixnumTemplate
	*(*int64)(unsafe.Pointer(&v.v)) = n
	return v
}

// AotFloat extracts a Float Value's float64 payload in pure Go without cgo.
func AotFloat(v Value) float64 {
	return *(*float64)(unsafe.Pointer(&v.v))
}

// AotFloatValue builds a Float Value in pure Go without cgo for finite/Inf
// values; NaN delegates to mrb.FloatValue so mruby assigns its NaN serial.
func (mrb *MrbState) AotFloatValue(f float64) Value {
	if math.IsNaN(f) {
		return mrb.FloatValue(f)
	}
	v := aotFloatTemplate
	*(*float64)(unsafe.Pointer(&v.v)) = f
	return v
}

// AotFloatCanRun reports whether float-specialized Go code may run (no Float
// operator redefinition and specialization not disabled by bailout).
func (mrb *MrbState) AotFloatCanRun() bool {
	return (mrb.aot == nil || mrb.aot.intDisabled == 0) && !mrb.AotFloatOpsRedefined()
}

// aotReceiverClass returns the mruby RClass pointer for recv in pure Go
// (zero cgo calls), matching mrb_class() in mruby/class.h.
func (mrb *MrbState) aotReceiverClass(recv Value) *C.struct_RClass {
	switch recv.Type() {
	case MrbTTFalse:
		if recv.IsNil() {
			return mrb.p.nil_class
		}
		return mrb.p.false_class
	case MrbTTTrue:
		return mrb.p.true_class
	case MrbTTInteger:
		return mrb.p.integer_class
	case MrbTTFloat:
		return mrb.p.float_class
	case MrbTTSymbol:
		return mrb.p.symbol_class
	case MrbTTCptr:
		return mrb.p.object_class
	default:
		if recv.Pointer() <= 65536 {
			return nil
		}
		return (*C.struct_RBasic)(aotObjPtr(recv)).c
	}
}

// AotDefineMethodTracked defines a compiled method like AotDefineMethod and
// records its installed mrb_method_t at slot so specialized Go functions can
// verify method dispatch via AotCompiledMethodOK without cgo on the hot path.
func (mrb *MrbState) AotDefineMethodTracked(slot int, target Value, mid MrbSym, cx *AotCtx, needCtx bool, fn AotFunc) {
	mrb.AotDefineMethodTrackedSig(slot, target, mid, cx, needCtx, fn, AotSig{})
}

// AotSig is the argument signature of a compiled method: its argument spec
// (the operand of the OP_ENTER of its bytecode) and the parameter list
// Method#parameters shows, "kind:name;kind:name". Known is false for a
// method whose signature is not known, which then takes any arguments.
type AotSig struct {
	Aspec  uint32
	KeyReq bool // a keyword is required: it counts in the arity
	Params string
	Known  bool
}

// info is the argument spec as the env of a compiled method or block keeps
// it: the spec, with bit 24 set when a keyword is required.
func (s AotSig) info() C.mrb_int {
	info := C.mrb_int(s.Aspec)
	if s.KeyReq {
		info |= 1 << 24
	}
	return info
}

// aotSigValue is the parameter array of sig, made once for all the procs
// that share it.
func (mrb *MrbState) aotSigValue(sig AotSig) Value {
	if !sig.Known {
		return nilValue
	}
	key := aotSigKey{sig.Params}
	if v, ok := mrb.aot.sigVals[key]; ok {
		return v
	}
	cparams := C.CString(sig.Params)
	defer C.free(unsafe.Pointer(cparams))
	v := Value{C._aot_params_new(mrb.p, cparams)}
	if mrb.aot.sigVals == nil {
		mrb.aot.sigVals = make(map[aotSigKey]Value)
	}
	mrb.aot.sigVals[key] = v
	return v
}

type aotSigKey struct{ params string }

// AotDefineMethodTrackedSig is AotDefineMethodTracked with the method's signature.
func (mrb *MrbState) AotDefineMethodTrackedSig(slot int, target Value, mid MrbSym, cx *AotCtx, needCtx bool, fn AotFunc, sig AotSig) {
	mrb.AotDefineMethodSig(target, mid, cx, needCtx, fn, sig)
	if slot < 0 {
		return
	}
	cls := mrb.ClassPtr(target)
	var found C.mrb_bool
	m := C._aot_intrinsic_method(mrb.p, cls.p, C.mrb_sym(mid), &found)
	if !bool(found) {
		return
	}
	if slot >= len(mrb.aot.compiledMethods) {
		grown := make([]C.mrb_method_t, slot+1)
		copy(grown, mrb.aot.compiledMethods)
		mrb.aot.compiledMethods = grown
	}
	mrb.aot.compiledMethods[slot] = m
}

// AotCompiledMethodOK reports whether calling mid on recv resolves to the exact
// compiled method recorded at slot (no monkey-patch, subclass override,
// singleton override, prepend, or refinement). Zero cgo on warm mruby cache;
// warms the cache once on a cold lookup.
func (mrb *MrbState) AotCompiledMethodOK(recv Value, mid MrbSym, slot int) bool {
	if mrb.aot == nil || slot < 0 || slot >= len(mrb.aot.compiledMethods) {
		return false
	}
	expected := mrb.aot.compiledMethods[slot]
	if expected == (C.mrb_method_t{}) {
		return false
	}
	if (mrb.p.refined_mids[0] | mrb.p.refined_mids[1] | mrb.p.refined_mids[2] | mrb.p.refined_mids[3]) != 0 {
		return false
	}
	oc := mrb.aotReceiverClass(recv)
	if oc == nil {
		return false
	}
	cmid := C.mrb_sym(mid)
	way0 := aotMethodCacheWay0(oc, cmid)
	mc0 := &mrb.p.cache[way0]
	if mc0.c == oc && mc0.mid == cmid {
		return mc0.m == expected
	}
	mc1 := &mrb.p.cache[way0+1]
	if mc1.c == oc && mc1.mid == cmid {
		return mc1.m == expected
	}
	// Cold cache: warm mruby's method cache once so subsequent calls stay 0-cgo, 0-alloc.
	return mrb.aotCacheMatchSlow(oc, cmid, expected)
}

// AotBytesBinary allocates an ASCII-8BIT (BINARY) Ruby String from b in a
// single cgo call and protects it in the current GC arena.
func (mrb *MrbState) AotBytesBinary(b []byte) Value {
	if len(b) == 0 {
		return Value{C._aot_bytes_binary(mrb.p, nil, 0)}
	}
	return Value{C._aot_bytes_binary(mrb.p, (*C.char)(unsafe.Pointer(&b[0])), C.mrb_int(len(b)))}
}

// AotTopCtx returns context for top level script code
func (mrb *MrbState) AotTopCtx() *AotCtx {
	mrb.AotInit()
	return mrb.aot.topCx
}

func (mrb *MrbState) aotExc() error {
	return &AotError{mrb, Value{C.mrb_obj_value(unsafe.Pointer(mrb.p.exc))}}
}

// AotRaiseValue converts error returned by compiled code into a value that
// the C trampoline raises in mruby.
func (mrb *MrbState) AotRaiseValue(err error) MrbValue {
	if mrb.p.exc != nil {
		return Value{C.mrb_obj_value(unsafe.Pointer(mrb.p.exc))}
	}
	var ae *AotError
	if errors.As(err, &ae) && !ae.Exc.IsNil() {
		mrb.p.exc = C._mrb_obj_ptr(ae.Exc.v)
		return ae.Exc
	}
	return mrb.Raise(mrb.ERuntimeError(), err.Error())
}

// AotSetExc sets pending exception and returns error
func (mrb *MrbState) AotSetExc(exc Value) error {
	C._aot_op(mrb.p, C.AOT_OP_RAISE, exc.v, nilValue.v, nilValue.v, 0)
	return mrb.aotExc()
}

// AotExcept implements OP_EXCEPT: returns pending exception and clears it
func (mrb *MrbState) AotExcept() Value {
	if mrb.p.exc == nil {
		return nilValue
	}
	v := Value{C.mrb_obj_value(unsafe.Pointer(mrb.p.exc))}
	mrb.p.exc = nil
	return v
}

// AotOp performs protected primitive operation (see go-aot.h AOT_OP_*)
func (mrb *MrbState) AotOp(op int, a, b, c Value, sym MrbSym) Value {
	mrb.aotStress()
	return Value{C._aot_op(mrb.p, C.int(op), a.v, b.v, c.v, C.mrb_sym(sym))}
}

// AOT primitive operation codes
const (
	AotOpConstGet       = C.AOT_OP_CONST_GET
	AotOpConstSet       = C.AOT_OP_CONST_SET
	AotOpCVGet          = C.AOT_OP_CV_GET
	AotOpCVSet          = C.AOT_OP_CV_SET
	AotOpIVSet          = C.AOT_OP_IV_SET
	AotOpDefineClass    = C.AOT_OP_DEFINE_CLASS
	AotOpDefineModule   = C.AOT_OP_DEFINE_MODULE
	AotOpSingletonClass = C.AOT_OP_SINGLETON_CLASS
	AotOpAryCat         = C.AOT_OP_ARY_CAT
	AotOpAryPush        = C.AOT_OP_ARY_PUSH
	AotOpArySplat       = C.AOT_OP_ARY_SPLAT
	AotOpArySet         = C.AOT_OP_ARY_SET
	AotOpHashSet        = C.AOT_OP_HASH_SET
	AotOpHashGet        = C.AOT_OP_HASH_GET
	AotOpHashCat        = C.AOT_OP_HASH_CAT
	AotOpStrCat         = C.AOT_OP_STR_CAT
	AotOpRangeNew       = C.AOT_OP_RANGE_NEW
	AotOpIntern         = C.AOT_OP_INTERN
	AotOpAlias          = C.AOT_OP_ALIAS
	AotOpUndef          = C.AOT_OP_UNDEF
	AotOpToProc         = C.AOT_OP_TO_PROC
	AotOpRescueP        = C.AOT_OP_RESCUE_P
	AotOpGVSet          = C.AOT_OP_GV_SET
	AotOpArgnumError    = C.AOT_OP_ARGNUM_ERROR
	AotOpRaise          = C.AOT_OP_RAISE
	AotOpYield          = C.AOT_OP_YIELD
	AotOpMethodAdded    = C.AOT_OP_METHOD_ADDED
	AotOpNoMatch        = C.AOT_OP_NOMATCH
	AotOpLocalJump      = C.AOT_OP_LOCALJUMP
	AotOpHashDup        = C.AOT_OP_HASH_DUP
	AotOpKArg           = C.AOT_OP_KARG
	AotOpKeyEnd         = C.AOT_OP_KEYEND
	AotOpEnsureAry      = C.AOT_OP_ENSURE_ARY
	AotOpEnsureHash     = C.AOT_OP_ENSURE_HASH
	AotOpEnsureStr      = C.AOT_OP_ENSURE_STR
	AotOpNoBlockError   = C.AOT_OP_NOBLOCK_ERROR
)

var aotGCStress = os.Getenv("ORUBY_AOT_GCSTRESS") != ""
var aotGCStressFull = os.Getenv("ORUBY_AOT_GCSTRESS") == "full"

func (mrb *MrbState) aotStress() {
	if aotGCStress {
		if aotGCStressFull {
			C.mrb_full_gc(mrb.p)
		} else {
			C.mrb_incremental_gc(mrb.p)
		}
	}
}

func valuesPtr(args []Value) *C.mrb_value {
	if len(args) == 0 {
		return nil
	}
	return (*C.mrb_value)(unsafe.Pointer(&args[0]))
}

// AotCall calls method mid on recv. fcall is true for receiver-less calls
// (private methods allowed). If kw is true the last element of args is a
// keyword arguments Hash.
func (mrb *MrbState) AotCall(self, recv Value, mid MrbSym, args []Value, blk Value, fcall, kw bool) (Value, error) {
	mrb.aotStress()
	if kw {
		return mrb.aotDispatch(2, recv, mid, nil, args, blk)
	}
	if mrb.aotSendFamily(mid) {
		return mrb.aotDispatch(0, recv, mid, nil, args, blk)
	}
	if res, err, ok := mrb.aotDirect(recv, mid, args, blk, fcall); ok {
		return res, err
	}
	var v Value
	if !fcall {
		v = Value{C._aot_funcall_public(mrb.p, self.v, recv.v, C.mrb_sym(mid), C.mrb_int(len(args)), valuesPtr(args), blk.v)}
	} else {
		v = Value{C._aot_funcall(mrb.p, recv.v, C.mrb_sym(mid), C.mrb_int(len(args)), valuesPtr(args), blk.v)}
	}
	if mrb.p.exc != nil {
		return nilValue, mrb.aotExc()
	}
	return v, nil
}

// AotCall0 calls method without arguments
func (mrb *MrbState) AotCall0(self, recv Value, mid MrbSym, fcall bool) (Value, error) {
	mrb.aotStress()
	if res, err, ok := mrb.aotDirect(recv, mid, nil, nilValue, fcall); ok {
		return res, err
	}
	var v Value
	if !fcall {
		v = Value{C._aot_funcall_public(mrb.p, self.v, recv.v, C.mrb_sym(mid), 0, nil, C.mrb_nil_value())}
	} else {
		v = Value{C._aot_funcall(mrb.p, recv.v, C.mrb_sym(mid), 0, nil, C.mrb_nil_value())}
	}
	if mrb.p.exc != nil {
		return nilValue, mrb.aotExc()
	}
	return v, nil
}

// aotSendFamily reports whether mid is send, __send__ or public_send. Entered
// from C these take send_method's funcall path, which calls any method (so
// public_send would not refuse a private one) and drops keyword arguments;
// aotDispatch resolves the target itself.
func (mrb *MrbState) aotSendFamily(mid MrbSym) bool {
	st := mrb.aot
	return st != nil && (mid == st.symSend || mid == st.symSend2 || mid == st.symPubSend)
}

//go:noinline
func (mrb *MrbState) aotCall1Slow(self, recv Value, mid MrbSym, a Value, fcall bool) (Value, error) {
	if mrb.aotSendFamily(mid) {
		return mrb.aotDispatch(0, recv, mid, nil, []Value{a}, nilValue)
	}
	var v Value
	if !fcall {
		v = Value{C._aot_funcall_public(mrb.p, self.v, recv.v, C.mrb_sym(mid), 1, &a.v, C.mrb_nil_value())}
	} else {
		v = Value{C._aot_funcall(mrb.p, recv.v, C.mrb_sym(mid), 1, &a.v, C.mrb_nil_value())}
	}
	if mrb.p.exc != nil {
		return nilValue, mrb.aotExc()
	}
	return v, nil
}

// AotCall1 calls method with one argument
func (mrb *MrbState) AotCall1(self, recv Value, mid MrbSym, a Value, fcall bool) (Value, error) {
	mrb.aotStress()
	if st := mrb.aot; st != nil && st.depth < aotMaxDirectDepth {
		slot := &st.argBuf[st.depth]
		slot[0] = a
		if res, err, ok := mrb.aotDirect(recv, mid, slot[:1], nilValue, fcall); ok {
			return res, err
		}
	}
	return mrb.aotCall1Slow(self, recv, mid, a, fcall)
}

//go:noinline
func (mrb *MrbState) aotCall2Slow(self, recv Value, mid MrbSym, a, b Value, fcall bool) (Value, error) {
	if mrb.aotSendFamily(mid) {
		return mrb.aotDispatch(0, recv, mid, nil, []Value{a, b}, nilValue)
	}
	var cbuf [2]C.mrb_value
	cbuf[0] = a.v
	cbuf[1] = b.v
	var v Value
	if !fcall {
		v = Value{C._aot_funcall_public(mrb.p, self.v, recv.v, C.mrb_sym(mid), 2, &cbuf[0], C.mrb_nil_value())}
	} else {
		v = Value{C._aot_funcall(mrb.p, recv.v, C.mrb_sym(mid), 2, &cbuf[0], C.mrb_nil_value())}
	}
	if mrb.p.exc != nil {
		return nilValue, mrb.aotExc()
	}
	return v, nil
}

// AotCall2 calls method with two arguments
func (mrb *MrbState) AotCall2(self, recv Value, mid MrbSym, a, b Value, fcall bool) (Value, error) {
	mrb.aotStress()
	if st := mrb.aot; st != nil && st.depth < aotMaxDirectDepth {
		slot := &st.argBuf[st.depth]
		slot[0] = a
		slot[1] = b
		if res, err, ok := mrb.aotDirect(recv, mid, slot[:2], nilValue, fcall); ok {
			return res, err
		}
	}
	return mrb.aotCall2Slow(self, recv, mid, a, b, fcall)
}

func (mrb *MrbState) aotDispatch(mode int, recv Value, mid MrbSym, tc unsafe.Pointer, args []Value, blk Value) (Value, error) {
	mrb.AotInit()
	argv := make([]Value, 0, len(args)+3)
	argv = append(argv, Value{C.mrb_int_value(mrb.p, C.mrb_int(mode))}, mrb.SymbolValue(mid))
	if tc == nil {
		argv = append(argv, nilValue)
	} else {
		argv = append(argv, Value{C.mrb_cptr_value(mrb.p, tc)})
	}
	argv = append(argv, args...)
	v := Value{C._aot_funcall(mrb.p, recv.v, C.mrb_sym(mrb.aot.symDispatch), C.mrb_int(len(argv)), valuesPtr(argv), blk.v)}
	if mrb.p.exc != nil {
		return nilValue, mrb.aotExc()
	}
	return v, nil
}

// AotSuper calls super method of current method context
func (mrb *MrbState) AotSuper(self Value, cx *AotCtx, args []Value, blk Value, kw bool) (Value, error) {
	mid, super := MrbSym(0), unsafe.Pointer(nil)
	if cx != nil {
		mid, super = cx.Mid, cx.Super
	}
	if mid == 0 || super == nil {
		// A block that is a method's body (define_method) has no method context
		// of its own: its caller's frame is the method, with its name and class.
		if m, tc := mrb.aotCiInfo(); m != 0 && tc != nil {
			mid, super = m, tc
		}
	}
	if mid == 0 || super == nil {
		e := mrb.ExcNew(mrb.ENoMethodError(), "super called outside of method")
		return nilValue, mrb.AotSetExc(e)
	}
	mode := 1
	if kw {
		mode |= 2
	}
	return mrb.aotDispatch(mode, self, mid, super, args, blk)
}

// AotYield calls block with arguments (OP_BLKCALL)
func (mrb *MrbState) AotYield(blk Value, args []Value) (Value, error) {
	mrb.aotStress()
	if blk.Type() != MrbTTProc {
		if blk.IsNil() {
			return nilValue, mrb.AotSetExc(mrb.ExcNew(mrb.ELocalJumpError(), "no block given (yield)"))
		}
		return nilValue, mrb.AotSetExc(mrb.ExcNew(mrb.ETypeError(), "wrong type (expected Proc)"))
	}
	if res, err, ok := mrb.aotYieldDirect(blk, args); ok {
		return res, err
	}
	v := Value{C._aot_yield(mrb.p, blk.v, C.mrb_int(len(args)), valuesPtr(args))}
	if mrb.p.exc != nil {
		return nilValue, mrb.aotExc()
	}
	return v, nil
}

// AotArgs returns arguments of current C function call. Keyword arguments
// are appended as last Hash argument.
func (mrb *MrbState) AotArgs() ([]Value, Value) {
	if mrb.hasFastArgs {
		args := make([]Value, len(mrb.fastArgs))
		copy(args, mrb.fastArgs)
		return args, nilValue
	}
	var a C.struct_aot_ci_args
	C._aot_ci_args(mrb.p, &a)
	argc := int(a.argc)
	kdict := Value{a.kdict}
	hasKw := kdict.v.tt == C.MRB_TT_HASH && C.mrb_hash_size(mrb.p, kdict.v) > 0
	n := argc
	if hasKw {
		n++
	}
	var args []Value
	if n > 0 {
		args = make([]Value, n)
		if argc > 0 {
			copy(args, unsafe.Slice((*Value)(unsafe.Pointer(a.argv)), argc))
		}
		if hasKw {
			args[argc] = kdict
		}
	}
	return args, Value{a.blk}
}

func (mrb *MrbState) aotCiInfo() (MrbSym, unsafe.Pointer) {
	if mrb.hasFastArgs {
		return 0, nil
	}
	return MrbSym(C._aot_ci_mid(mrb.p)), unsafe.Pointer(C._aot_ci_target_class(mrb.p))
}

// AotDefTarget returns class where def defines methods
func (mrb *MrbState) AotDefTarget(cx *AotCtx) Value {
	if cx != nil {
		if !cx.DefTarget.IsNil() {
			return cx.DefTarget
		}
		if cx.Cref != nil {
			return cx.Cref.Class
		}
	}
	return mrb.ObjectClass().Value()
}

// AotCrefClass returns innermost lexical class (Object at top level)
func (mrb *MrbState) AotCrefClass(cx *AotCtx) Value {
	if cx != nil && cx.Cref != nil {
		return cx.Cref.Class
	}
	return mrb.ObjectClass().Value()
}

// AotClassCtx creates context for class body executed with OP_EXEC
func (mrb *MrbState) AotClassCtx(cx *AotCtx, class Value) *AotCtx {
	var up *AotCref
	if cx != nil {
		up = cx.Cref
	}
	return &AotCtx{Cref: &AotCref{Class: class, Up: up}}
}

//go:noinline
func (mrb *MrbState) aotConstGetSlow(cref *AotCref, sym MrbSym, canCache bool, key *C.struct_mrb_irep, h uint32) Value {
	for c := cref; c != nil; c = c.Up {
		if C.mrb_const_defined_at(mrb.p, c.Class.v, C.mrb_sym(sym)) != false {
			v := mrb.AotOp(AotOpConstGet, c.Class, nilValue, nilValue, sym)
			if canCache && mrb.p.exc == nil && c.Class.Pointer() > 65536 {
				clsFlags := (*(*uint32)(unsafe.Add(aotObjPtr(c.Class), 8))) >> 12
				if (clsFlags & (1 << 9)) == 0 { // !MRB_FL_CLASS_CONST_FLAGS
					cc := &mrb.p.const_cache[h]
					cc.irep = key
					cc.sym = C.mrb_sym(sym)
					cc.value = v.v
				}
			}
			return v
		}
	}
	base := mrb.ObjectClass().Value()
	if cref != nil {
		base = cref.Class
	}
	if canCache {
		var cacheable C.mrb_bool
		v := Value{C._aot_const_get_vm_cacheable(mrb.p, base.v, C.mrb_sym(sym), &cacheable)}
		if bool(cacheable) && mrb.p.exc == nil {
			cc := &mrb.p.const_cache[h]
			cc.irep = key
			cc.sym = C.mrb_sym(sym)
			cc.value = v.v
		}
		return v
	}
	return mrb.AotOp(C.AOT_OP_CONST_GET_VM, base, nilValue, nilValue, sym)
}

// AotConstGet looks up constant using lexical scope, then ancestors.
// Uses mruby's const_cache in pure Go (zero cgo, zero alloc on warm cache) for
// simple scopes, automatically invalidated by mruby on any const_set /
// const_remove / autoload / include / prepend.
func (mrb *MrbState) AotConstGet(cx *AotCtx, sym MrbSym) Value {
	var cref *AotCref
	if cx != nil {
		cref = cx.Cref
	}
	canCache := cref == nil || cref.Up == nil
	var key *C.struct_mrb_irep
	var h uint32
	if canCache {
		baseCls := mrb.p.object_class
		if cref != nil && cref.Class.Pointer() > 65536 {
			baseCls = (*C.struct_RClass)(aotObjPtr(cref.Class))
		}
		key = (*C.struct_mrb_irep)(unsafe.Pointer(baseCls))
		h = aotConstHash(uintptr(unsafe.Pointer(key)), uintptr(sym))
		cc := &mrb.p.const_cache[h]
		if cc.irep == key && cc.sym == C.mrb_sym(sym) {
			return mrb.aotProtect(Value{cc.value})
		}
	}
	return mrb.aotConstGetSlow(cref, sym, canCache, key, h)
}

// AotConstSet sets constant in innermost lexical class
func (mrb *MrbState) AotConstSet(cx *AotCtx, sym MrbSym, v Value) {
	mrb.AotOp(AotOpConstSet, mrb.AotCrefClass(cx), v, nilValue, sym)
}

func (mrb *MrbState) aotCVBase(cx *AotCtx, self Value) Value {
	if cx != nil {
		for c := cx.Cref; c != nil; c = c.Up {
			if c.Class.Type() != MrbTTSClass {
				return c.Class
			}
		}
	}
	return mrb.ObjectClass().Value()
}

// AotCVGet reads class variable
func (mrb *MrbState) AotCVGet(cx *AotCtx, self Value, sym MrbSym) Value {
	return mrb.AotOp(AotOpCVGet, mrb.aotCVBase(cx, self), nilValue, nilValue, sym)
}

// AotCVSet sets class variable
func (mrb *MrbState) AotCVSet(cx *AotCtx, self Value, sym MrbSym, v Value) {
	mrb.AotOp(AotOpCVSet, mrb.aotCVBase(cx, self), v, nilValue, sym)
}

// AotNewEnv allocates GC visible register file of n registers
func (mrb *MrbState) AotNewEnv(n int, up *AotEnv) *AotEnv {
	parent := nilValue
	if up != nil {
		parent = up.Ary
	}
	ary := Value{C._aot_frame_new(mrb.p, C.mrb_int(n), parent.v)}
	ptr := C._aot_frame_ptr(ary.v)
	return &AotEnv{R: unsafe.Slice((*Value)(unsafe.Pointer(ptr)), n), Ary: ary, Up: up, Root: unsafe.Pointer(mrb.p.root_c)}
}

// AotHasHook reports whether an asynchronous VM hook (thread preemption,
// Thread#raise, Thread#kill, Timeout, or OS signal) is armed.
func (mrb *MrbState) AotHasHook() bool {
	return mrb.p.code_fetch_hook != nil
}

// AotNeedBackEdge reports whether a loop back-edge needs to trim the GC
// arena or service an armed VM hook.
func (mrb *MrbState) AotNeedBackEdge(ai int32) bool {
	return int32(mrb.p.gc.arena_idx) > ai+64 || mrb.p.code_fetch_hook != nil
}

// AotHookPending reports whether a hook is armed: a signal, a Timeout deadline
// or a thread switch waits for the next instruction. A typed integer loop
// (compiler/intloop.go) leaves for the generic loop, which services it.
func (mrb *MrbState) AotHookPending() bool {
	return mrb.p.code_fetch_hook != nil
}

// AotIntCanRun reports whether integer-specialized code may run on the
// current thread.
func (mrb *MrbState) AotIntCanRun() bool {
	return (mrb.aot == nil || mrb.aot.intDisabled == 0) && !mrb.AotIntOpsRedefined()
}

// AotIntDisable disables integer-specialized entry on the current thread
// while a fallback call is in progress.
func (mrb *MrbState) AotIntDisable() {
	mrb.AotInit()
	mrb.aot.intDisabled++
}

// AotIntEnable re-enables integer-specialized entry on the current thread.
func (mrb *MrbState) AotIntEnable() {
	if mrb.aot != nil {
		mrb.aot.intDisabled--
	}
}

// AotBackEdge is called on loop back edges: frees GC arena, makes frame
// registers visible to the incremental GC again, and services any armed VM
// hook. Returns true when an exception or unwind is pending.
func (mrb *MrbState) AotBackEdge(ai int32, env *AotEnv) bool {
	if int32(mrb.p.gc.arena_idx) > ai+64 {
		C._aot_arena_reset(mrb.p, C.int(ai), env.Ary.v)
	}
	if mrb.p.code_fetch_hook != nil {
		C._aot_poll(mrb.p)
		return mrb.p.exc != nil
	}
	return false
}

//go:noinline
func (mrb *MrbState) aotWBSlow(ary Value) {
	C._aot_write_barrier(mrb.p, ary.v)
}

// AotWB runs GC write barrier for env register file when env.Ary is black.
func (mrb *MrbState) AotWB(env *AotEnv) {
	if env == nil || env.Ary.Pointer() <= 65536 {
		return
	}
	up := aotObjPtr(env.Ary)
	if ((*(*uint32)(unsafe.Add(up, 8))) & (7 << 8)) == (4 << 8) { // GC_BLACK
		mrb.aotWBSlow(env.Ary)
	}
}

// AotWBVal runs GC write barrier for env register file only when v is a heap
// object and env.Ary is black. Immediate values skip the check entirely.
func (mrb *MrbState) AotWBVal(env *AotEnv, v Value) {
	if v.v.tt <= C.MRB_TT_CPTR || env == nil || env.Ary.Pointer() <= 65536 {
		return
	}
	up := aotObjPtr(env.Ary)
	if ((*(*uint32)(unsafe.Add(up, 8))) & (7 << 8)) == (4 << 8) { // GC_BLACK
		mrb.aotWBSlow(env.Ary)
	}
}

// AotProtectRegs re-protects heap values held in Go register file after
// arena restore and services any armed VM hook. Returns true when an
// exception or unwind is pending.
func (mrb *MrbState) AotProtectRegs(ai int32, r []Value) bool {
	C._aot_arena_restore(mrb.p, C.int(ai))
	for i := range r {
		if r[i].v.tt > C.MRB_TT_CPTR {
			C.mrb_gc_protect(mrb.p, r[i].v)
		}
	}
	if mrb.p.code_fetch_hook != nil {
		C._aot_poll(mrb.p)
		return mrb.p.exc != nil
	}
	return false
}

type aotBlockData struct {
	fn        AotFunc
	outerSelf Value
	cx        *AotCtx
	env       *AotEnv
}

//export go_aot_handle_free
func go_aot_handle_free(stateIdx C.mrb_int, id C.mrb_int) {
	mrb := lookupMrbStateIndex(int(stateIdx))
	if mrb == nil {
		return
	}
	if mrb.aot != nil {
		delete(mrb.aot.blocks, int64(id))
	}
}

func (mrb *MrbState) aotBlockTrampoline(m *MrbState, self Value) MrbValue {
	id := int64(C._aot_current_block_id(mrb.p))
	bd := mrb.aot.blocks[id]
	if bd == nil {
		return mrb.Raise(mrb.ERuntimeError(), "compiled block state not found")
	}
	args, blk := mrb.AotArgs()
	bcx := bd.cx
	if C._aot_block_self_lexical(mrb.p, self.v) != false {
		self = bd.outerSelf
	} else if tc := unsafe.Pointer(C._aot_ci_target_class(mrb.p)); tc != nil {
		nc := *bd.cx
		nc.DefTarget = Value{C.mrb_obj_value(tc)}
		bcx = &nc
	}
	res, err := bd.fn(mrb, self, args, blk, bcx, bd.env)
	if err != nil {
		return mrb.AotRaiseValue(err)
	}
	return res
}

// AotBlock creates block (or lambda) Proc for compiled function fn.
func (mrb *MrbState) AotBlock(fn AotFunc, outerSelf Value, cx *AotCtx, env *AotEnv, lambda bool) Value {
	return mrb.AotBlockSig(fn, outerSelf, cx, env, lambda, AotSig{})
}

// AotBlockSig is AotBlock with the block's signature, which Proc#arity and
// #parameters answer from. It does not make the VM check arguments: a block
// takes them as a block does, and a lambda checks its own.
func (mrb *MrbState) AotBlockSig(fn AotFunc, outerSelf Value, cx *AotCtx, env *AotEnv, lambda bool, sig AotSig) Value {
	mrb.AotInit()
	st := mrb.aot
	envVal := nilValue
	if env != nil {
		envVal = env.Ary
	}
	if cx == nil {
		cx = st.topCx
	}
	st.nextBlock++
	id := st.nextBlock
	st.blocks[id] = &aotBlockData{fn: fn, outerSelf: outerSelf, cx: cx, env: env}
	params := mrb.aotSigValue(sig)
	p := C._aot_proc_new(mrb.p, C.mrb_int(st.trampIdx), C.mrb_int(id), envVal.v, outerSelf.v, C.mrb_bool(lambda), C.mrb_bool(sig.Known), sig.info(), params.v)
	return Value{C.mrb_obj_value(unsafe.Pointer(p))}
}

// AotDefineMethod defines compiled method fn. If needCtx is true, a new
// context with method name and target class (for super) is created on
// each call.
func (mrb *MrbState) AotDefineMethod(target Value, mid MrbSym, cx *AotCtx, needCtx bool, fn AotFunc) {
	mrb.AotDefineMethodSig(target, mid, cx, needCtx, fn, AotSig{})
}

// AotDefineMethodSig is AotDefineMethod with the method's signature: the VM
// checks the argument count and keywords as for a bytecode method, and
// Method#arity and #parameters answer from it.
func (mrb *MrbState) AotDefineMethodSig(target Value, mid MrbSym, cx *AotCtx, needCtx bool, fn AotFunc, sig AotSig) {
	if cx == nil {
		cx = mrb.AotTopCtx()
	}
	cls := mrb.ClassPtr(target)
	defClass := unsafe.Pointer(cls.p)
	f := func(mrb *MrbState, self Value) MrbValue {
		args, blk := mrb.AotArgs()
		mcx := cx
		if needCtx {
			mid2, tc := mrb.aotCiInfo()
			if tc == nil {
				tc = defClass
			}
			if mid2 == 0 {
				mid2 = mid
			}
			mcx = &AotCtx{Cref: cx.Cref, Mid: mid2, Super: tc}
		}
		res, err := fn(mrb, self, args, blk, mcx, nil)
		if err != nil {
			return mrb.AotRaiseValue(err)
		}
		return res
	}
	idx := mrb.registerMrbFuncT(f)
	mrb.AotInit()
	if idx >= len(mrb.aot.methods) {
		grown := make([]*aotMethod, idx+16)
		copy(grown, mrb.aot.methods)
		mrb.aot.methods = grown
	}
	mrb.aot.methods[idx] = &aotMethod{fn: fn, cx: cx, needCtx: needCtx}
	params := mrb.aotSigValue(sig)
	C._aot_define_method(mrb.p, cls.p, C.mrb_sym(mid), C.mrb_int(idx), C.mrb_bool(sig.Known), C.uint32_t(sig.Aspec), sig.info(), params.v)
}

//go:noinline
func (mrb *MrbState) aotLookupCompiledSlow(recv Value, mid MrbSym, fcall bool) (int, *C.struct_RClass) {
	var owner *C.struct_RClass
	idx := int(C._aot_lookup_compiled(mrb.p, recv.v, C.mrb_sym(mid), boolInt(fcall), &owner))
	return idx, owner
}

// aotDirect calls compiled method of recv directly when the method lookup
// resolves to one. Uses pure-Go 2-way method cache probing (zero cgo and zero
// Go heap allocation on warm cache), falling back to C only on cache miss.
func (mrb *MrbState) aotDirect(recv Value, mid MrbSym, args []Value, blk Value, fcall bool) (res Value, err error, ok bool) {
	st := mrb.aot
	if st == nil || st.depth >= aotMaxDirectDepth || mrb.hasFastArgs {
		return nilValue, nil, false
	}
	if blk.v.tt != C.MRB_TT_FALSE && blk.v.tt != C.MRB_TT_PROC {
		return nilValue, nil, false // needs to_proc conversion
	}
	idx, owner, fastVal, _, _, hit := mrb.aotMethodIdxFromCache(recv, mid, fcall)
	if !hit {
		idx, owner = mrb.aotLookupCompiledSlow(recv, mid, fcall)
	}
	if idx <= aotFastAttrRead && blk.IsNil() {
		switch idx {
		case aotFastAttrRead:
			if len(args) == 0 {
				return mrb.AotIVGet(recv, MrbSym(fastVal)), nil, true
			}
			return nilValue, nil, false
		case aotFastAttrWrite:
			if len(args) == 1 && mrb.AotIVSetImmediate(recv, MrbSym(fastVal), args[0]) {
				return args[0], nil, true
			}
			return nilValue, nil, false
		case aotFastStructRef:
			if len(args) == 0 {
				if v, ok := mrb.aotStructSlotRef(recv, int(fastVal)); ok {
					return v, nil, true
				}
			}
			return nilValue, nil, false
		}
	}
	if idx < 0 || idx >= len(st.methods) {
		return nilValue, nil, false
	}
	mi := st.methods[idx]
	if mi == nil {
		return nilValue, nil, false
	}
	if mrb.p.code_fetch_hook != nil {
		C._aot_poll(mrb.p)
		if mrb.p.exc != nil {
			return nilValue, mrb.aotExc(), true
		}
	}
	mcx := mi.cx
	if mi.needCtx {
		mcx = &AotCtx{Cref: mi.cx.Cref, Mid: mid, Super: unsafe.Pointer(owner)}
	}
	// callee runs in this call frame: give it the default (public) scope
	ci := mrb.p.c.ci
	vis := ci.vis
	ci.vis = 0
	st.depth++
	res, err = mi.fn(mrb, recv, args, blk, mcx, nil)
	st.depth--
	mrb.p.c.ci.vis = vis
	return res, err, true
}

// aotYieldDirect runs compiled block blk directly
func (mrb *MrbState) aotYieldDirect(blk Value, args []Value) (res Value, err error, ok bool) {
	st := mrb.aot
	if st == nil || st.depth >= aotMaxDirectDepth {
		return nilValue, nil, false
	}
	id := int64(C._aot_proc_block_id(blk.v))
	if id < 0 {
		return nilValue, nil, false
	}
	bd := st.blocks[id]
	if bd == nil {
		return nilValue, nil, false
	}
	if mrb.p.code_fetch_hook != nil {
		C._aot_poll(mrb.p)
		if mrb.p.exc != nil {
			return nilValue, mrb.aotExc(), true
		}
	}
	st.depth++
	res, err = bd.fn(mrb, bd.outerSelf, args, nilValue, bd.cx, bd.env)
	st.depth--
	return res, err, true
}

// AotDepthEnter accounts a direct Go call between compiled methods; it
// returns false when the call must go through the VM (stack depth limit)
func (mrb *MrbState) AotDepthEnter() bool {
	st := mrb.aot
	if st == nil || st.depth >= aotMaxDirectDepth {
		return false
	}
	st.depth++
	return true
}

// AotDepthLeave ends direct call accounted by AotDepthEnter
func (mrb *MrbState) AotDepthLeave() { mrb.aot.depth-- }

func boolInt(b bool) C.int {
	if b {
		return 1
	}
	return 0
}

// AotScope is saved method definition scope of current call frame
type AotScope struct {
	s C.struct_aot_scope
}

// AotScopePush starts new method definition scope for class body
// (private false) or top level code (private true, defined methods are
// private as in the VM).
func (mrb *MrbState) AotScopePush(class Value, private bool) *AotScope {
	vis := 0
	if private {
		vis = 1
	}
	s := &AotScope{}
	C._aot_scope_push(mrb.p, C.int(vis), &s.s)
	return s
}

// AotScopePop restores method definition scope
func (mrb *MrbState) AotScopePop(s *AotScope) {
	C._aot_scope_pop(mrb.p, &s.s)
}

// AotEnter implements OP_ENTER argument setup. It fills registers r from
// args and blk according to aspec, and returns the number of optional
// arguments supplied.
func (mrb *MrbState) AotEnter(r []Value, args []Value, blk Value, aspec uint32, strict bool) (int, error) {
	m1 := int((aspec >> 18) & 0x1f)
	o := int((aspec >> 13) & 0x1f)
	rest := int((aspec >> 12) & 0x1)
	m2 := int((aspec >> 7) & 0x1f)
	key := int((aspec >> 2) & 0x1f)
	kdictFlag := int((aspec >> 1) & 0x1)
	noblock := (aspec>>23)&0x1 != 0
	kd := 0
	if key > 0 || kdictFlag > 0 {
		kd = 1
	}
	length := m1 + o + rest + m2

	if noblock && !blk.IsNil() {
		mrb.AotOp(AotOpNoBlockError, nilValue, nilValue, nilValue, 0)
		return 0, mrb.aotExc()
	}

	kdict := nilValue
	argc := len(args)
	if kd == 1 && argc > 0 && args[argc-1].Type() == MrbTTHash && argc > m1+m2 {
		kdict = mrb.AotOp(AotOpHashDup, args[argc-1], nilValue, nilValue, 0)
		if mrb.p.exc != nil {
			return 0, mrb.aotExc()
		}
		args = args[:argc-1]
		argc--
	}

	if strict {
		if argc < m1+m2 || (rest == 0 && argc > length) {
			// same message as mruby VM (argnum_error)
			maxArgs := length // -1 when a rest argument takes any number
			if rest != 0 {
				maxArgs = -1
			}
			mrb.AotOp(AotOpArgnumError, mrb.FixnumValue(argc), mrb.FixnumValue(m1+m2), mrb.FixnumValue(maxArgs), 0)
			return 0, mrb.aotExc()
		}
	} else if length > 1 && argc == 1 && args[0].Type() == MrbTTArray {
		ary := args[0]
		n := int(C._aot_ary_len(ary.v))
		args = make([]Value, n)
		for i := 0; i < n; i++ {
			args[i] = Value{C.mrb_ary_entry(ary.v, C.mrb_int(i))}
		}
		argc = n
	}

	skip := 0
	if argc < length {
		mlen := m2
		if argc < m1+m2 {
			mlen = 0
			if m1 < argc {
				mlen = argc - m1
			}
		}
		// mandatory and optional arguments
		for i := 0; i < argc-mlen; i++ {
			r[i+1] = args[i]
		}
		for i := argc; i < m1; i++ {
			r[i+1] = nilValue
		}
		// post mandatory arguments
		for i := 0; i < mlen; i++ {
			r[length-m2+1+i] = args[argc-mlen+i]
		}
		for i := mlen; i < m2; i++ {
			r[length-m2+1+i] = nilValue
		}
		if rest == 1 {
			r[m1+o+1] = mrb.AryNew().Value()
		}
		if o > 0 && argc > m1+m2 {
			skip = argc - m1 - m2
		}
	} else {
		for i := 0; i < m1+o; i++ {
			r[i+1] = args[i]
		}
		rnum := 0
		if rest == 1 {
			rnum = argc - m1 - o - m2
			ary := mrb.AryNewCapa(rnum)
			for i := 0; i < rnum; i++ {
				C.mrb_ary_push(mrb.p, ary.v, args[m1+o+i].v)
			}
			r[m1+o+1] = ary.Value()
		}
		if m2 > 0 && argc-m2 > m1 {
			for i := 0; i < m2; i++ {
				r[m1+o+rest+1+i] = args[m1+o+rnum+i]
			}
		}
		skip = o
	}

	kwPos := length + kd
	blkPos := kwPos + 1
	if blkPos < len(r) {
		r[blkPos] = blk
	}
	if kd == 1 {
		if kdict.IsNil() {
			kdict = mrb.HashNew().Value()
		}
		r[kwPos] = kdict
	}
	return skip, nil
}

// AotArgnumError raises wrong number of arguments error
func (mrb *MrbState) AotArgnumError(argc, min, max int) error {
	mrb.AotOp(AotOpArgnumError, mrb.FixnumValue(argc), mrb.FixnumValue(min), mrb.FixnumValue(max), 0)
	return mrb.aotExc()
}

// AotBlockArgs expands single Array argument for non-lambda blocks with
// more than one parameter
func (mrb *MrbState) AotBlockArgs(args []Value) []Value {
	if len(args) == 1 && args[0].Type() == MrbTTArray {
		ary := args[0]
		n := int(C._aot_ary_len(ary.v))
		res := make([]Value, n)
		for i := 0; i < n; i++ {
			res[i] = Value{C.mrb_ary_entry(ary.v, C.mrb_int(i))}
		}
		return res
	}
	return args
}

// AotAryValues returns copy of array elements (splat arguments)
func (mrb *MrbState) AotAryValues(ary Value) []Value {
	if ary.Type() != MrbTTArray {
		return []Value{ary}
	}
	n := int(C._aot_ary_len(ary.v))
	res := make([]Value, n)
	for i := 0; i < n; i++ {
		res[i] = Value{C.mrb_ary_entry(ary.v, C.mrb_int(i))}
	}
	return res
}

// AotAryNew creates array from values
func (mrb *MrbState) AotAryNew(vals ...Value) Value {
	return Value{C.mrb_ary_new_from_values(mrb.p, C.mrb_int(len(vals)), valuesPtr(vals))}
}

// AotAryRef returns array element (nil when out of range) in pure Go without cgo.
func (mrb *MrbState) AotAryRef(ary Value, i int) Value {
	v, ok := mrb.AotAryRefRaw(ary, i)
	if !ok {
		return nilValue
	}
	return mrb.aotProtect(v)
}

// AotIVGet reads instance variable in pure Go for shaped RObjects (zero cgo),
// falling back to C for unshaped / special objects.
func (mrb *MrbState) AotIVGet(obj Value, sym MrbSym) Value {
	if v, ok := mrb.AotIVGetShaped(obj, sym); ok {
		return v
	}
	return Value{C._aot_iv_get(mrb.p, obj.v, C.mrb_sym(sym))}
}

// AotGVGet reads global variable (value is kept in GC arena)
func (mrb *MrbState) AotGVGet(sym MrbSym) Value {
	return Value{C._aot_gv_get(mrb.p, C.mrb_sym(sym))}
}

// AotAryLen returns length of array in pure Go without cgo.
func (mrb *MrbState) AotAryLen(ary Value) int {
	_, n := aotAryMem(ary)
	return n
}

// AotKwHash creates keyword arguments hash from key/value pairs
func (mrb *MrbState) AotKwHash(kv ...Value) Value {
	h := Value{C.mrb_hash_new_capa(mrb.p, C.mrb_int(len(kv)/2))}
	for i := 0; i+1 < len(kv); i += 2 {
		mrb.AotOp(AotOpHashSet, h, kv[i], kv[i+1], 0)
		if mrb.p.exc != nil {
			return nilValue
		}
	}
	return h
}

// AotApost implements OP_APOST: *r[a], r[a+1]..r[a+post] = ary[pre..]
func (mrb *MrbState) AotApost(r []Value, a, pre, post int) {
	v := r[a]
	if v.Type() != MrbTTArray {
		v = mrb.AotAryNew(v)
	}
	n := mrb.AotAryLen(v)
	if n > pre+post {
		rest := make([]Value, n-pre-post)
		for i := range rest {
			rest[i] = mrb.AotAryRef(v, pre+i)
		}
		r[a] = mrb.AotAryNew(rest...)
		for i := 0; i < post; i++ {
			r[a+1+i] = mrb.AotAryRef(v, n-post+i)
		}
	} else {
		r[a] = mrb.AryNew().Value()
		idx := 0
		for ; idx+pre < n; idx++ {
			r[a+1+idx] = mrb.AotAryRef(v, pre+idx)
		}
		for ; idx < post; idx++ {
			r[a+1+idx] = nilValue
		}
	}
}

// AotArgAry implements OP_ARGARY: builds arguments array of current
// method (from register file stack starting at r[1]) for zsuper.
func (mrb *MrbState) AotArgAry(stack []Value, b uint32) (Value, Value, Value) {
	m1 := int((b >> 11) & 0x3f)
	rest := int((b >> 10) & 0x1)
	m2 := int((b >> 5) & 0x1f)
	kd := int((b >> 4) & 0x1)
	st := stack[1:]
	var vals []Value
	vals = append(vals, st[:m1]...)
	if rest == 1 {
		if st[m1].Type() == MrbTTArray {
			vals = append(vals, mrb.AotAryValues(st[m1])...)
		}
	}
	if m2 > 0 {
		vals = append(vals, st[m1+rest:m1+rest+m2]...)
	}
	ary := mrb.AotAryNew(vals...)
	if kd == 1 {
		return ary, st[m1+rest+m2], st[m1+rest+m2+1]
	}
	return ary, st[m1+rest+m2], nilValue
}

// AotBlkPush implements OP_BLKPUSH, reads block from register file
func (mrb *MrbState) AotBlkPush(stack []Value, b uint32) (Value, error) {
	m1 := int((b >> 11) & 0x3f)
	rest := int((b >> 10) & 0x1)
	m2 := int((b >> 5) & 0x1f)
	kd := int((b >> 4) & 0x1)
	off := m1 + rest + m2 + kd + 1
	if off >= len(stack) || stack[off].IsNil() {
		return nilValue, mrb.AotSetExc(mrb.ExcNew(mrb.ELocalJumpError(), "unexpected yield"))
	}
	return stack[off], nil
}

func (mrb *MrbState) aotUnwind(cls RClass, val Value, tag uintptr, idx int) error {
	mrb.AotInit()
	st := mrb.aot
	exc := mrb.ExcNew(cls, "unexpected break or return")
	C.mrb_iv_set(mrb.p, exc.v, C.mrb_sym(st.symVal), val.v)
	C.mrb_iv_set(mrb.p, exc.v, C.mrb_sym(st.symTag), C.mrb_int_value(mrb.p, C.mrb_int(tag)))
	C.mrb_iv_set(mrb.p, exc.v, C.mrb_sym(st.symIdx), C.mrb_int_value(mrb.p, C.mrb_int(idx)))
	return mrb.AotSetExc(exc)
}

func (mrb *MrbState) aotCatchUnwind(cls RClass, tag uintptr, idx int) (Value, bool) {
	if mrb.p.exc == nil || mrb.aot == nil {
		return nilValue, false
	}
	exc := Value{C.mrb_obj_value(unsafe.Pointer(mrb.p.exc))}
	if C.mrb_class(mrb.p, exc.v) != cls.p {
		return nilValue, false
	}
	st := mrb.aot
	t := Value{C.mrb_iv_get(mrb.p, exc.v, C.mrb_sym(st.symTag))}
	i := Value{C.mrb_iv_get(mrb.p, exc.v, C.mrb_sym(st.symIdx))}
	if t.Int64() != int64(tag) || i.Int() != idx {
		return nilValue, false
	}
	mrb.p.exc = nil
	return Value{C.mrb_iv_get(mrb.p, exc.v, C.mrb_sym(st.symVal))}, true
}

// AotBreak raises break from block idx created in frame env. When the call
// which received the block is no longer running, LocalJumpError is raised.
func (mrb *MrbState) AotBreak(val Value, env *AotEnv, idx int) error {
	mrb.AotInit()
	if env != nil && (env.Root != unsafe.Pointer(mrb.p.root_c) || (idx < 64 && env.Active&(1<<uint(idx)) == 0)) {
		return mrb.AotSetExc(mrb.ExcNew(mrb.ELocalJumpError(), "break from proc-closure"))
	}
	return mrb.aotUnwind(mrb.aot.breakClass, val, uintptr(unsafe.Pointer(env)), idx)
}

// AotBlockCallBegin marks call site passing block literal idx as running
func (env *AotEnv) AotBlockCallBegin(idx int) {
	if idx < 64 {
		env.Active |= 1 << uint(idx)
	}
}

// AotBlockCallEnd marks call site passing block literal idx as finished
func (env *AotEnv) AotBlockCallEnd(idx int) {
	if idx < 64 {
		env.Active &^= 1 << uint(idx)
	}
}

// AotCatchBreak checks if pending exception is break from block idx created
// in frame env. If it is, exception is cleared and break value returned.
func (mrb *MrbState) AotCatchBreak(env *AotEnv, idx int) (Value, bool) {
	if mrb.aot == nil {
		return nilValue, false
	}
	return mrb.aotCatchUnwind(mrb.aot.breakClass, uintptr(unsafe.Pointer(env)), idx)
}

// AotReturn raises non-local return to method frame home
func (mrb *MrbState) AotReturn(val Value, home *AotEnv) error {
	mrb.AotInit()
	if home == nil || home.Done || home.Root != unsafe.Pointer(mrb.p.root_c) {
		return mrb.AotSetExc(mrb.ExcNew(mrb.ELocalJumpError(), "unexpected return"))
	}
	return mrb.aotUnwind(mrb.aot.returnClass, val, uintptr(unsafe.Pointer(home)), 0)
}

// AotCatchReturn checks if pending exception is return to frame home
func (mrb *MrbState) AotCatchReturn(home *AotEnv) (Value, bool) {
	if mrb.aot == nil {
		return nilValue, false
	}
	return mrb.aotCatchUnwind(mrb.aot.returnClass, uintptr(unsafe.Pointer(home)), 0)
}

// AotExcIsUnwind returns true if pending exception is break or return,
// which rescue clauses must not catch
func (mrb *MrbState) AotExcIsUnwind() bool {
	if mrb.p.exc == nil {
		return false
	}
	exc := Value{C.mrb_obj_value(unsafe.Pointer(mrb.p.exc))}
	if exc.Type() == MrbTTBreak {
		return true // VM break unwinding across compiled frames
	}
	if mrb.aot == nil {
		return false
	}
	c := C.mrb_class(mrb.p, exc.v)
	return c == mrb.aot.breakClass.p || c == mrb.aot.returnClass.p
}

// AotIsUnwindValue returns true if v is break or return exception object
func (mrb *MrbState) AotIsUnwindValue(v Value) bool {
	if mrb.aot == nil || v.Type() != MrbTTException {
		return false
	}
	c := C.mrb_class(mrb.p, v.v)
	return c == mrb.aot.breakClass.p || c == mrb.aot.returnClass.p
}

// AotLocalJumpCheck converts escaped break/return exceptions to
// LocalJumpError at top level
func (mrb *MrbState) AotLocalJumpCheck() {
	if mrb.AotExcIsUnwind() {
		// break/return without target frame
		mrb.p.exc = nil
		e := mrb.ExcNew(mrb.ELocalJumpError(), "break from proc-closure")
		mrb.p.exc = C._mrb_obj_ptr(e.v)
	}
}

// AotSym returns symbol value
func (mrb *MrbState) AotSym(sym MrbSym) Value {
	return Value{C.mrb_symbol_value(C.mrb_sym(sym))}
}

// AotStrNew creates new String
func (mrb *MrbState) AotStrNew(s string) Value {
	if len(s) == 0 {
		return Value{C.mrb_str_new(mrb.p, nil, 0)}
	}
	cs := unsafe.Pointer(unsafe.StringData(s))
	return Value{C.mrb_str_new(mrb.p, (*C.char)(cs), C.mrb_int(len(s)))}
}

// AotStrDup duplicates String (literals are copied on each evaluation)
func (mrb *MrbState) AotStrDup(s Value) Value {
	return Value{C.mrb_str_dup(mrb.p, s.v)}
}

// AotChilledLiteralTag identifies the compiler's chilled-string marker.
const AotChilledLiteralTag = C.ORUBY_CHILLED_DEBUG_TAG

// AotChillString marks an AOT string literal as chilled.
func (mrb *MrbState) AotChillString(s Value) {
	C.aot_chill_string(s.v)
}

// AotIsNil is nil check without C call (MRB_NO_BOXING layout)
func (v Value) AotIsNil() bool {
	return v.v.tt == C.MRB_TT_FALSE && *(*int64)(unsafe.Pointer(&v.v)) == 0
}

// AotProtect protects heap value in GC arena in pure Go (zero cgo unless
// the arena needs to grow).
func (mrb *MrbState) AotProtect(v Value) {
	mrb.aotProtect(v)
}

// AotIsPlainArray returns true if v is an instance of Array (not subclass)
func (mrb *MrbState) AotIsPlainArray(v Value) bool {
	return v.v.tt == C.MRB_TT_ARRAY && (*C.struct_RBasic)(v.unsafePtr()).c == mrb.p.array_class
}

// AotIsPlainHash returns true if v is an instance of Hash (not subclass)
func (mrb *MrbState) AotIsPlainHash(v Value) bool {
	return v.v.tt == C.MRB_TT_HASH && (*C.struct_RBasic)(v.unsafePtr()).c == mrb.p.hash_class
}

// AotF64 converts IEEE754 bits to float64 (exact float literals)
func AotF64(bits uint64) float64 { return math.Float64frombits(bits) }

// AotKeyP implements OP_KEY_P
func (mrb *MrbState) AotKeyP(kdict Value, sym MrbSym) Value {
	if kdict.v.tt != C.MRB_TT_HASH {
		return False
	}
	if C.mrb_hash_key_p(mrb.p, kdict.v, C.mrb_symbol_value(C.mrb_sym(sym))) != false {
		return True
	}
	return False
}

// AotBlockGiven returns true if blk is a block
func AotBlockGiven(blk Value) Value {
	if blk.AotIsNil() {
		return False
	}
	return True
}

func (mrb *MrbState) aotDefinedStr(ok bool, s string) Value {
	if ok {
		return mrb.AotStrNew(s)
	}
	return nilValue
}

func (mrb *MrbState) aotConstDefined(cx *AotCtx, sym MrbSym) bool {
	var cref *AotCref
	if cx != nil {
		cref = cx.Cref
	}
	for c := cref; c != nil; c = c.Up {
		if C.mrb_const_defined_at(mrb.p, c.Class.v, C.mrb_sym(sym)) != false {
			return true
		}
	}
	base := mrb.ObjectClass().Value()
	if cref != nil {
		base = cref.Class
	}
	return C._aot_const_defined_vm(mrb.p, base.v, C.mrb_sym(sym)) != false
}

// AotDefinedConst implements defined?(Const) in lexical scope of cx
func (mrb *MrbState) AotDefinedConst(cx *AotCtx, sym Value) Value {
	if sym.Type() != MrbTTSymbol {
		return nilValue
	}
	return mrb.aotDefinedStr(mrb.aotConstDefined(cx, sym.Symbol()), "constant")
}

// AotDefinedConstPath implements defined?(Parent::Child)
func (mrb *MrbState) AotDefinedConstPath(cx *AotCtx, start, path Value) Value {
	if path.Type() != MrbTTArray {
		return nilValue
	}
	n := mrb.AotAryLen(path)
	if n == 0 || mrb.AotAryRef(path, 0).Type() != MrbTTSymbol {
		return nilValue
	}
	// nil: the first name is looked up where the code stands; otherwise
	// (::X, or an expression's value) from the object the caller evaluated
	outer := start
	i := 0
	if start.IsNil() {
		first := mrb.AotAryRef(path, 0).Symbol()
		if !mrb.aotConstDefined(cx, first) {
			return nilValue
		}
		if n == 1 {
			return mrb.aotDefinedStr(true, "constant")
		}
		outer = mrb.AotConstGet(cx, first)
		if mrb.p.exc != nil {
			mrb.p.exc = nil
			return nilValue
		}
		i = 1
	}
	for ; i < n; i++ {
		switch outer.Type() {
		case MrbTTClass, MrbTTModule, MrbTTSClass:
		default:
			return nilValue
		}
		name := mrb.AotAryRef(path, i)
		if name.Type() != MrbTTSymbol {
			return nilValue
		}
		if C.mrb_const_defined(mrb.p, outer.v, C.mrb_sym(name.Symbol())) == false {
			return nilValue
		}
		if i < n-1 {
			// a name before the last is read (it may be an autoload)
			v, err := mrb.AotCall(nilValue, outer, mrb.Intern("const_get"), []Value{name}, nilValue, true, false)
			if err != nil {
				mrb.p.exc = nil
				return nilValue
			}
			outer = v
		}
	}
	return mrb.aotDefinedStr(true, "constant")
}

// AotDefinedCVar implements defined?(@@var)
func (mrb *MrbState) AotDefinedCVar(cx *AotCtx, self, sym Value) Value {
	if sym.Type() != MrbTTSymbol {
		return nilValue
	}
	base := mrb.aotCVBase(cx, self)
	return mrb.aotDefinedStr(C.mrb_mod_cv_defined(mrb.p, (*C.struct_RClass)(base.unsafePtr()), C.mrb_sym(sym.Symbol())) != false, "class variable")
}

// AotDefinedSuper implements defined?(super)
func (mrb *MrbState) AotDefinedSuper(cx *AotCtx) Value {
	if cx == nil || cx.Super == nil {
		return nilValue
	}
	return mrb.aotDefinedStr(C._aot_super_defined(mrb.p, (*C.struct_RClass)(cx.Super), C.mrb_sym(cx.Mid)) != false, "super")
}

// AotDefinedYield implements defined?(yield)
func (mrb *MrbState) AotDefinedYield(blk Value) Value {
	return mrb.aotDefinedStr(!blk.AotIsNil(), "yield")
}

// AotRunVM runs bytecode (RITE, with debug info) in the VM as a file loaded
// by require: at the top level, with its own local variables. It is the entry
// of a module that stays bytecode because it needs its frame (eval, binding,
// using), see compiler/vmtier.go.
func (mrb *MrbState) AotRunVM(codeBase64, file string) (Value, error) {
	code, err := base64.StdEncoding.DecodeString(codeBase64)
	if err != nil {
		return nilValue, err
	}
	cxt := mrb.MrbCcontextNew()
	defer cxt.Free()
	cxt.Filename(file)
	return mrb.LoadIrepBytesWrapped(code, cxt, mrb.ObjectClass(), mrb.TopSelf())
}
